#!/usr/bin/env node
// kalkal Alfred Workflow — Script Filter
// Usage: cal <date> [calendar]
// Examples: cal 15 Ramadan 1446 | cal 2024-3-22 | cal 1446/9/15 hijri | cal today

const path = require('path');

// cal-engine.js is generated by build.sh from js/hijri.js (const Cal → module.exports)
const Cal = require(path.join(__dirname, 'cal-engine.js'));

// Calendar registry
const CALENDARS = {
  hijri:      { name: 'Hijri (AH)',         toJD: (y,m,d) => Cal.hijriToJD(y,m,d,'IIc'),     fromJD: jd => Cal.jdToHijri(jd,'IIc'),     months: ['Muharram','Safar','Rabi I','Rabi II','Jumada I','Jumada II','Rajab','Shaban','Ramadan','Shawwal','Dhu al-Qada','Dhu al-Hijja'] },
  gregorian:  { name: 'Gregorian',          toJD: Cal.gregorianToJD, fromJD: Cal.jdToGregorian, months: ['January','February','March','April','May','June','July','August','September','October','November','December'] },
  julian:     { name: 'Julian',             toJD: Cal.julianToJD,    fromJD: Cal.jdToJulian,    months: ['January','February','March','April','May','June','July','August','September','October','November','December'] },
  coptic:     { name: 'Coptic',             toJD: Cal.copticToJD,    fromJD: Cal.jdToCoptic,    months: ['Thout','Paopi','Hathor','Koiak','Tobi','Meshir','Paremhat','Parmouti','Pashons','Paoni','Epip','Mesori','Epagomenai'] },
  ethiopian:  { name: 'Ethiopian',          toJD: Cal.ethiopianToJD, fromJD: Cal.jdToEthiopian, months: ['Mäskäräm','Ṭəqəmt','Ḥədar','Taḫśaś','Ṭər','Yäkatit','Mägabit','Miyazya','Gənbot','Säne','Ḥamle','Nähase','Pagumän'] },
  solarHijri: { name: 'Solar Hijri',        toJD: Cal.solarHijriToJD, fromJD: Cal.jdToSolarHijri, months: ['Farvardin','Ordibehešt','Ḫordād','Tir','Mordād','Šahrivar','Mehr','Ābān','Āḏar','Dey','Bahman','Esfand'] },
  hebrew:     { name: 'Hebrew',             toJD: Cal.hebrewToJD,    fromJD: Cal.jdToHebrew,    months: ['Tishrei','Cheshvan','Kislev','Tevet','Shevat','Adar','Adar II','Nisan','Iyar','Sivan','Tammuz','Av','Elul'] },
  byzantine:  { name: 'Byzantine',          toJD: Cal.byzantineToJD, fromJD: Cal.jdToByzantine, months: ['September','October','November','December','January','February','March','April','May','June','July','August'] },
  syriac:     { name: 'Syriac',             toJD: Cal.syriacToJD,    fromJD: Cal.jdToSyriac,    months: ['Kānūn ath-Thānī','Shbāṭ','Ādhār','Nīsān','Ayyār','Ḥzīrān','Tammūz','Āb','Aylūl','Tishrīn al-Awwal','Tishrīn ath-Thānī','Kānūn al-Awwal'] },
  rumi:       { name: 'Rūmī',              toJD: Cal.rumiToJD,      fromJD: Cal.jdToRumi,      months: ['March','April','May','June','July','August','September','October','November','December','January','February'] },
  armenian:   { name: 'Armenian',           toJD: Cal.armenianToJD,  fromJD: Cal.jdToArmenian,  months: ['Navasard','Hoṙi','Sahmi','Trē','Kʻaloč','Aracʻ','Mehekan','Areg','Ahekan','Mareri','Margacʻ','Hroticʻ','Aweleacʻ'] },
  egyptian:   { name: 'Egyptian',           toJD: Cal.egyptianToJD,  fromJD: Cal.jdToEgyptian,  months: ['Thoth','Phaophi','Athyr','Choiak','Tybi','Mechir','Phamenoth','Pharmuthi','Pachons','Payni','Epiphi','Mesore','Epagomenai'] },
  auc:        { name: 'Ab Urbe Condita',    toJD: Cal.aucToJD,       fromJD: Cal.jdToAuc,       months: ['January','February','March','April','May','June','July','August','September','October','November','December'] },
  olympiad:   { name: 'Olympiad',           toJD: Cal.olympiadToJD,  fromJD: Cal.jdToOlympiad,  months: ['January','February','March','April','May','June','July','August','September','October','November','December'] },
};

const WEEKDAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

// Month name → { calId, month } lookup (case-insensitive, diacritics-stripped)
const MONTH_LOOKUP = {};
for (const [calId, cal] of Object.entries(CALENDARS)) {
  cal.months.forEach((name, i) => {
    const key = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (!MONTH_LOOKUP[key]) MONTH_LOOKUP[key] = { calId, month: i + 1 };
  });
}

// Short Gregorian month names
const SHORT_MONTHS = {
  jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12,
  january:1, february:2, march:3, april:4, june:6, july:7, august:8, september:9, october:10, november:11, december:12,
};

// Calendar name aliases for the trailing calendar token
const CAL_ALIASES = {
  // English short
  greg: 'gregorian', gregorian: 'gregorian', ce: 'gregorian', ad: 'gregorian',
  jul: 'julian', julian: 'julian',
  hijri: 'hijri', ah: 'hijri', islamic: 'hijri',
  solar: 'solarHijri', shamsi: 'solarHijri', iranian: 'solarHijri', jalali: 'solarHijri', sh: 'solarHijri',
  heb: 'hebrew', hebrew: 'hebrew', am: 'hebrew',
  cop: 'coptic', coptic: 'coptic',
  eth: 'ethiopian', ethiopian: 'ethiopian',
  byz: 'byzantine', byzantine: 'byzantine',
  syr: 'syriac', syriac: 'syriac',
  rumi: 'rumi',
  arm: 'armenian', armenian: 'armenian',
  egy: 'egyptian', egyptian: 'egyptian',
  auc: 'auc', roman: 'auc',
  olympiad: 'olympiad', oly: 'olympiad',
  // Polish
  gregorianski: 'gregorian', julianski: 'julian', koptyjski: 'coptic', hebrajski: 'hebrew',
  // Arabic-ish transliterations
  hijry: 'hijri', miladi: 'gregorian',
};

// Hijri month aliases (common transliteration variants)
const HIJRI_MONTH_ALIASES = {
  muharram: 1, moharram: 1,
  safar: 2, safer: 2,
  'rabi1': 3, 'rabii': 3, 'rabiʿ': 3, 'rabi': 3,
  'rabi2': 4, 'rabiii': 4,
  'jumada1': 5, 'jumadai': 5, 'jumada': 5, 'jamadi': 5,
  'jumada2': 6, 'jumadaii': 6, 'jamadii': 6,
  rajab: 7, rajeb: 7, receb: 7,
  shaban: 8, shaaban: 8, shaban: 8, szaban: 8,
  ramadan: 9, ramazan: 9, ramzan: 9,
  shawwal: 10, shawwaal: 10, szawwal: 10,
  'dhulqada': 11, 'zulqada': 11, 'zilkade': 11,
  'dhulhijja': 12, 'zulhijja': 12, 'dhulhijjah': 12, 'zilhicce': 12,
};

// Hebrew month aliases
const HEBREW_MONTH_ALIASES = {
  tishri: 1, tishrei: 1,
  heshvan: 2, cheshvan: 2, marcheshvan: 2,
  kislev: 3,
  tevet: 4, teves: 4, tebet: 4,
  shevat: 5, shvat: 5,
  adar: 6, 'adari': 6,
  'adarii': 7, 'adar2': 7, 'adarsheni': 7,
  nisan: 8, nissan: 8,
  iyar: 9, iyyar: 9,
  sivan: 10, siwan: 10,
  tammuz: 11, tamuz: 11,
  av: 12, ab: 12,
  elul: 13,
};

// Resolve a token to a month number + calendar using all alias tables
function resolveMonth(token) {
  const t = token.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  // Primary month lookup (from CALENDARS registry)
  if (MONTH_LOOKUP[t]) return MONTH_LOOKUP[t];
  // Short Gregorian
  if (SHORT_MONTHS[t]) return { calId: 'gregorian', month: SHORT_MONTHS[t] };
  // Hijri aliases
  if (HIJRI_MONTH_ALIASES[t]) return { calId: 'hijri', month: HIJRI_MONTH_ALIASES[t] };
  // Hebrew aliases
  if (HEBREW_MONTH_ALIASES[t]) return { calId: 'hebrew', month: HEBREW_MONTH_ALIASES[t] };
  return null;
}

// Resolve a token to a calendar ID using aliases
function resolveCalendar(token) {
  const t = token.toLowerCase();
  if (CAL_ALIASES[t]) return CAL_ALIASES[t];
  // Direct calendar ID match
  if (CALENDARS[t]) return t;
  // Partial match on calendar name
  for (const [id, cal] of Object.entries(CALENDARS)) {
    if (cal.name.toLowerCase().replace(/[()]/g, '').includes(t)) return id;
  }
  return null;
}

function dayOffset(n) {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return { year: d.getFullYear(), month: d.getMonth() + 1, day: d.getDate(), calId: 'gregorian' };
}

function parseQuery(q) {
  q = q.trim();
  if (!q) return null;

  // --- Relative dates ---
  if (/^(today|dzisiaj|hodiau|hoy|dziś|bugün|alyawm|ebenau|ma|vandaag)$/i.test(q)) return dayOffset(0);
  if (/^(tomorrow|jutro|morgau|mañana|yarın|ghadan|morgen)$/i.test(q)) return dayOffset(1);
  if (/^(yesterday|wczoraj|hierau|ayer|dün|ams|gestern)$/i.test(q)) return dayOffset(-1);

  // --- JDN direct input: "jd 2460749" or "jdn 2460749.5" ---
  const jdMatch = q.match(/^(?:jd|jdn)\s+([\d.]+)$/i);
  if (jdMatch) {
    const jd = Number(jdMatch[1]);
    if (!isNaN(jd)) return { jd };
  }

  // --- BCE/BC notation: "586 bce" or "44 bc gregorian" ---
  const bceMatch = q.match(/^(\d+)\s*(?:bce?|p\.?n\.?e\.?|av\.?\s*j\.?-?c\.?)\s*(.*)$/i);
  if (bceMatch) {
    const year = -Number(bceMatch[1]) + 1; // astronomical year: 1 BCE = 0, 2 BCE = -1
    const rest = bceMatch[2].trim();
    const calId = rest ? (resolveCalendar(rest) || 'julian') : 'julian';
    return { year, month: 1, day: 1, calId };
  }

  const tokens = q.split(/[\s,]+/);
  let calId = null;

  // Check if last token is a calendar alias
  const lastResolved = resolveCalendar(tokens[tokens.length - 1]);
  if (lastResolved) {
    calId = lastResolved;
    tokens.pop();
  }

  // Also check for "bce/bc" as second-to-last for "586 bce julian"
  // (handled above, but in case tokens remain)

  const cleaned = tokens.join(' ');

  // --- Month name present: "15 Ramadan 1446", "Ramadan 15 1446", "Ramadan 1446" ---
  for (let i = 0; i < tokens.length; i++) {
    const match = resolveMonth(tokens[i]);
    if (match) {
      const nums = tokens.filter((_, j) => j !== i).map(Number).filter(n => !isNaN(n));
      if (nums.length >= 2) {
        // Two numbers + month name → day + year
        let [a, b] = nums;
        let year, day;
        if (a > 31) { year = a; day = b; }
        else if (b > 31) { year = b; day = a; }
        else { day = a; year = b; }
        return { year, month: match.month, day, calId: calId || match.calId };
      }
      if (nums.length === 1) {
        // One number + month name → assume it's year, day=1: "Ramadan 1446"
        return { year: nums[0], month: match.month, day: 1, calId: calId || match.calId };
      }
    }
  }

  // --- D/M/Y or Y/M/D with separators: "1446/9/15", "22.03.2024", "15-9-1446" ---
  const dateMatch = cleaned.match(/^(-?\d+)[\/\-.](\d{1,2})[\/\-.](-?\d+)$/);
  if (dateMatch) {
    const a = Number(dateMatch[1]), b = Number(dateMatch[2]), c = Number(dateMatch[3]);
    let year, month, day;
    if (a > 31) {
      // Y/M/D: "1446/9/15" or "2024-3-22"
      year = a; month = b; day = c;
    } else if (c > 31) {
      // D/M/Y: "22.03.2024" or "15-9-1446"
      day = a; month = b; year = c;
    } else {
      // All small — ambiguous, try D/M/Y if middle ≤ 12, else Y/M/D
      if (b <= 12) { day = a; month = b; year = c; }
      else { year = a; month = b; day = c; }
    }
    if (!calId) calId = year > 1600 ? 'gregorian' : 'hijri';
    return { year, month, day, calId };
  }

  // --- Three bare numbers: "15 9 1446" ---
  const nums = tokens.map(Number).filter(n => !isNaN(n));
  if (nums.length === 3) {
    let [a, b, c] = nums;
    if (a > 31) return { year: a, month: b, day: c, calId: calId || (a > 1600 ? 'gregorian' : 'hijri') };
    if (c > 31) return { year: c, month: b, day: a, calId: calId || (c > 1600 ? 'gregorian' : 'hijri') };
    return { year: c, month: b, day: a, calId: calId || 'hijri' };
  }

  // --- Two numbers: "9 1446" → month + year, day=1 ---
  if (nums.length === 2) {
    let [a, b] = nums;
    let year, month;
    if (a > 12) { year = a; month = b; }
    else if (b > 12) { year = b; month = a; }
    else { month = a; year = b; }
    if (!calId) calId = year > 1600 ? 'gregorian' : 'hijri';
    return { year, month, day: 1, calId };
  }

  // --- Single year: "1446" or "1446 hijri" → 1st of 1st month ---
  if (nums.length === 1 && tokens.length <= 1) {
    const year = nums[0];
    if (!calId) calId = year > 1600 ? 'gregorian' : 'hijri';
    return { year, month: 1, day: 1, calId };
  }

  return null;
}

function formatDate(result, cal) {
  const monthName = cal.months[result.month - 1] || `M${result.month}`;
  return `${result.day} ${monthName} ${result.year}`;
}

// Fuzzy-match a query against calendar IDs and names. Returns matching IDs sorted by relevance.
function matchCalendars(filter, exclude) {
  if (!filter) return Object.keys(CALENDARS).filter(id => id !== exclude);
  const f = filter.toLowerCase();
  const scored = [];
  for (const [id, cal] of Object.entries(CALENDARS)) {
    if (id === exclude) continue;
    const name = cal.name.toLowerCase();
    // Check alias table too
    const aliasMatch = CAL_ALIASES[f] === id;
    if (aliasMatch) { scored.push({ id, score: 0 }); continue; }
    if (id.startsWith(f)) { scored.push({ id, score: 1 }); continue; }
    if (name.startsWith(f)) { scored.push({ id, score: 2 }); continue; }
    if (id.includes(f) || name.includes(f)) { scored.push({ id, score: 3 }); continue; }
    // Fuzzy: all chars of filter appear in order in id or name
    if (fuzzyMatch(f, id) || fuzzyMatch(f, name)) { scored.push({ id, score: 4 }); continue; }
  }
  scored.sort((a, b) => a.score - b.score);
  return scored.map(s => s.id);
}

function fuzzyMatch(needle, haystack) {
  let ni = 0;
  for (let hi = 0; hi < haystack.length && ni < needle.length; hi++) {
    if (haystack[hi] === needle[ni]) ni++;
  }
  return ni === needle.length;
}

function convert(query) {
  // Split on ">" to detect target calendar filter
  let datePart = query;
  let targetFilter = null;
  const arrowIdx = query.indexOf('>');
  if (arrowIdx !== -1) {
    datePart = query.substring(0, arrowIdx);
    targetFilter = query.substring(arrowIdx + 1).trim();
  }

  const parsed = parseQuery(datePart);
  if (!parsed) {
    return {
      items: [{
        title: 'Enter a date to convert',
        subtitle: '15 Ramadan 1446 · 2024-3-22 · today · jdn 2460749 · 586 bce · 1446',
        valid: false,
        icon: { path: 'icon.png' }
      }]
    };
  }

  let jd;
  let calId;
  let sourceLabel;

  if (parsed.jd !== undefined) {
    jd = parsed.jd;
    calId = null;
    sourceLabel = `JDN ${jd}`;
  } else {
    const { year, month, day } = parsed;
    calId = parsed.calId;
    const sourceCal = CALENDARS[calId];
    if (!sourceCal) {
      return { items: [{ title: `Unknown calendar: ${calId}`, valid: false, icon: { path: 'icon.png' } }] };
    }

    try {
      jd = sourceCal.toJD(year, month, day);
    } catch (e) {
      return { items: [{ title: `Invalid date: ${day}/${month}/${year} ${sourceCal.name}`, subtitle: e.message, valid: false, icon: { path: 'icon.png' } }] };
    }

    if (isNaN(jd)) {
      return { items: [{ title: `Invalid date: ${day}/${month}/${year} ${sourceCal.name}`, valid: false, icon: { path: 'icon.png' } }] };
    }

    sourceLabel = `${sourceCal.name}: ${formatDate({ year, month, day }, sourceCal)}`;
  }

  const dow = WEEKDAYS[Cal.getDayOfWeek(jd)];
  const items = [];

  // Determine which target calendars to show
  let ordered;
  if (targetFilter !== null) {
    // User typed ">..." — filter/fuzzy-match target calendars
    ordered = matchCalendars(targetFilter, calId);
  } else {
    // Default: primary calendars first, then the rest
    const PRIMARY = ['gregorian', 'hijri', 'julian', 'solarHijri', 'hebrew', 'coptic'];
    ordered = [
      ...PRIMARY.filter(id => id !== calId),
      ...Object.keys(CALENDARS).filter(id => id !== calId && !PRIMARY.includes(id))
    ];
  }

  for (const targetId of ordered) {
    const target = CALENDARS[targetId];
    try {
      const result = target.fromJD(jd);
      if (!result || isNaN(result.year)) continue;
      const formatted = formatDate(result, target);
      items.push({
        uid: targetId,
        title: formatted,
        subtitle: `${target.name} — ${dow}`,
        arg: formatted,
        text: { copy: formatted, largetype: `${formatted}\n${target.name}\n${dow}` },
        icon: { path: 'icon.png' },
        mods: {
          cmd: { subtitle: `JDN ${jd}`, arg: String(jd) },
          alt: { subtitle: `Copy: ${result.day}/${result.month}/${result.year}`, arg: `${result.day}/${result.month}/${result.year}` }
        }
      });
    } catch (e) {
      // skip calendars that can't handle this date
    }
  }

  if (items.length === 0) {
    if (targetFilter !== null) {
      return { items: [{ title: `No calendar matching "${targetFilter}"`, subtitle: `${sourceLabel} — type a calendar name after >`, valid: false, icon: { path: 'icon.png' } }] };
    }
    return { items: [{ title: 'No results', subtitle: `Could not convert ${sourceLabel}`, valid: false, icon: { path: 'icon.png' } }] };
  }

  // Enrich first item with source context
  items[0].subtitle = `${sourceLabel} → ${items[0].subtitle}`;

  return { items };
}

// Main
const query = process.argv.slice(2).join(' ');
process.stdout.write(JSON.stringify(convert(query)));
